    private static string? GetHashExtensionValue(ApiDependency dependency)
    {
        if (dependency.Extensions?.TryGetValue(GenerationConfiguration.KiotaHashManifestExtensionKey, out var node) ==
            true && node is JsonValue value && value.GetValueKind() is JsonValueKind.String)
        {
            return value.GetValue<string>();
        }
        return null;
    }
